#!/usr/bin/env node
import { budget, eta, formatRate, formatSize, parseRate } from "../src/index.mjs";

const HELP = `ratewise — transfer rates, ETAs and data budgets for humans

Usage
  ratewise eta <size> <rate> [--long]     ratewise eta "3 GB" "25 MB/s"      → 2m
  ratewise rate <rate> [--per s|m|h|d]    ratewise rate "20 GB/day" --per s → 231 kB/s
  ratewise budget <rate> <duration>       ratewise budget "100 Mbit/s" 1h   → 45 GB

Flags
  --long      Spell durations out (2 minutes)
  --per       Period for rate output (default s)
  --binary    Use KiB, MiB, GiB…
  --bits      Show bits (Mbit) instead of bytes`;

const args = process.argv.slice(2);
const flags = new Set(args.filter((arg) => arg.startsWith("--") && arg !== "--per"));
const perIndex = args.indexOf("--per");
const per = perIndex === -1 ? "s" : args[perIndex + 1];
const words = args.filter((arg, index) => !arg.startsWith("--") && (perIndex === -1 || index !== perIndex + 1));
const [command, first, second] = words;
const unitOptions = { binary: flags.has("--binary"), bits: flags.has("--bits") };

try {
  if (!command || flags.has("--help") || command === "help") {
    console.log(HELP);
  } else if (command === "eta" && first && second) {
    console.log(eta(first, second, { long: flags.has("--long") }));
  } else if (command === "rate" && first) {
    const value = parseRate(first);
    if (Number.isNaN(value)) throw new TypeError(`Unrecognised rate: ${first}`);
    console.log(formatRate(value, { per, ...unitOptions }));
  } else if (command === "budget" && first && second) {
    console.log(formatSize(budget(first, second), unitOptions));
  } else {
    console.error(HELP);
    process.exitCode = 2;
  }
} catch (error) {
  console.error(`ratewise: ${error.message}`);
  process.exitCode = 1;
}

import { bytesPerUnit, DURATION_LADDER, DURATION_MS, PER_SECONDS, SIZE_LABELS } from "./units.mjs";

const QUANTITY = /^\s*([+-]?(?:\d+\.?\d*|\.\d+))\s*([a-zA-Z]*)\s*$/;

/** Parses "1.5 GB", "2 KiB", "100 Mbit" or "100" into bytes. NaN if unrecognised. */
export function parseSize(text) {
  if (typeof text !== "string") return NaN;
  const match = QUANTITY.exec(text);
  if (!match) return NaN;
  const factor = bytesPerUnit(match[2]);
  return factor === undefined ? NaN : Number(match[1]) * factor;
}

/** Parses "90s", "2 hours" or "1.5d" into milliseconds. NaN if unrecognised. */
export function parseDuration(text) {
  if (typeof text !== "string") return NaN;
  const match = QUANTITY.exec(text);
  if (!match) return NaN;
  const factor = match[2] === "" ? 1 : DURATION_MS.get(match[2].toLowerCase());
  return factor === undefined ? NaN : Number(match[1]) * factor;
}

/**
 * Parses "<size>/<period>" or "<size> per <period>" into bytes per second.
 * The period may carry its own amount, e.g. "1 GB / 2h".
 */
export function parseRate(text) {
  if (typeof text !== "string") return NaN;
  const parts = text.split(/\s*(?:\/|\bper\b)\s*/i);
  if (parts.length !== 2) return NaN;
  const bytes = parseSize(parts[0]);
  const period = /^[a-zA-Z]/.test(parts[1]) ? `1 ${parts[1]}` : parts[1];
  const ms = parseDuration(period);
  if (Number.isNaN(bytes) || Number.isNaN(ms) || ms <= 0) return NaN;
  return bytes / (ms / 1000);
}

/** Formats bytes for people: 1337 → "1.34 kB". */
export function formatSize(bytes, { binary = false, bits = false } = {}) {
  if (typeof bytes !== "number" || !Number.isFinite(bytes)) {
    throw new TypeError(`Expected a finite number of bytes, got ${bytes}`);
  }
  const labels = SIZE_LABELS[bits ? (binary ? "binaryBits" : "bits") : binary ? "binary" : "decimal"];
  const step = binary ? 1024 : 1000;
  let amount = Math.abs(bits ? bytes * 8 : bytes);
  let power = 0;
  while (amount >= step && power < labels.length - 1) {
    amount /= step;
    power += 1;
  }
  amount = roundReadable(amount);
  if (amount >= step && power < labels.length - 1) {
    amount = roundReadable(amount / step);
    power += 1;
  }
  const sign = bytes < 0 && amount !== 0 ? "-" : "";
  return `${sign}${amount} ${labels[power]}`;
}

/** Formats a rate in bytes per second: 1337 → "1.34 kB/s". */
export function formatRate(bytesPerSecond, { per = "s", binary = false, bits = false } = {}) {
  const seconds = PER_SECONDS[per];
  if (seconds === undefined) throw new RangeError(`Unknown period "${per}"; use s, m, h or d.`);
  return `${formatSize(bytesPerSecond * seconds, { binary, bits })}/${per}`;
}

/** Formats milliseconds as "2m" or, with long, "2 minutes". */
export function formatDuration(ms, { long = false } = {}) {
  if (typeof ms !== "number" || !Number.isFinite(ms)) {
    throw new TypeError(`Expected a finite number of milliseconds, got ${ms}`);
  }
  const magnitude = Math.abs(ms);
  const rung = DURATION_LADDER.find((candidate) => magnitude >= candidate.size);
  if (!rung) {
    const whole = Math.round(ms);
    return long ? `${whole} ms` : `${whole}ms`;
  }
  const count = Math.round(ms / rung.size);
  if (!long) return `${count}${rung.short}`;
  return `${count} ${rung.long}${magnitude >= rung.size * 1.5 ? "s" : ""}`;
}

/** How long moving `size` takes at `rate`, as a readable duration. */
export function eta(size, rate, options = {}) {
  const bytes = toBytes(size);
  const bytesPerSecond = toRate(rate);
  if (bytesPerSecond <= 0) throw new RangeError("Rate must be greater than zero.");
  return formatDuration((bytes / bytesPerSecond) * 1000, options);
}

/** Bytes moved at `rate` during `duration` (milliseconds or text like "1h"). */
export function budget(rate, duration) {
  const bytesPerSecond = toRate(rate);
  const ms = typeof duration === "number" ? duration : parseDuration(duration);
  if (!Number.isFinite(ms)) throw new TypeError(`Unrecognised duration: ${duration}`);
  return bytesPerSecond * (ms / 1000);
}

function toBytes(size) {
  const bytes = typeof size === "number" ? size : parseSize(size);
  if (!Number.isFinite(bytes)) throw new TypeError(`Unrecognised size: ${size}`);
  return bytes;
}

function toRate(rate) {
  const value = typeof rate === "number" ? rate : parseRate(rate);
  if (!Number.isFinite(value)) throw new TypeError(`Unrecognised rate: ${rate}`);
  return value;
}

// Three significant digits, or every integer digit when there are more.
function roundReadable(amount) {
  if (amount === 0) return 0;
  const integerDigits = Math.floor(Math.log10(amount)) + 1;
  return Number(amount.toPrecision(Math.max(3, integerDigits)));
}

// Unit tables shared by the size, duration and rate helpers.

const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;
const WEEK = 7 * DAY;
const YEAR = 365.25 * DAY;
const MONTH = YEAR / 12;

/** Duration words (lower-case) mapped to milliseconds. */
export const DURATION_MS = new Map([
  ...["ms", "msec", "msecs", "millisecond", "milliseconds"].map((word) => [word, 1]),
  ...["s", "sec", "secs", "second", "seconds"].map((word) => [word, SECOND]),
  ...["m", "min", "mins", "minute", "minutes"].map((word) => [word, MINUTE]),
  ...["h", "hr", "hrs", "hour", "hours"].map((word) => [word, HOUR]),
  ...["d", "day", "days"].map((word) => [word, DAY]),
  ...["w", "wk", "wks", "week", "weeks"].map((word) => [word, WEEK]),
  ...["mo", "month", "months"].map((word) => [word, MONTH]),
  ...["y", "yr", "yrs", "year", "years"].map((word) => [word, YEAR]),
]);

/** Largest-first ladder used when describing a duration to people. */
export const DURATION_LADDER = [
  { size: YEAR, short: "y", long: "year" },
  { size: MONTH, short: "mo", long: "month" },
  { size: WEEK, short: "w", long: "week" },
  { size: DAY, short: "d", long: "day" },
  { size: HOUR, short: "h", long: "hour" },
  { size: MINUTE, short: "m", long: "minute" },
  { size: SECOND, short: "s", long: "second" },
];

/** Seconds in each "per" period accepted by formatRate. */
export const PER_SECONDS = { s: 1, m: 60, h: 3600, d: 86400 };

const PREFIXES = ["", "k", "m", "g", "t", "p", "e", "z", "y"];

/** Display labels for each unit family, indexed by power. */
export const SIZE_LABELS = {
  decimal: ["B", "kB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"],
  binary: ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"],
  bits: ["bit", "kbit", "Mbit", "Gbit", "Tbit", "Pbit", "Ebit", "Zbit", "Ybit"],
  binaryBits: ["bit", "Kibit", "Mibit", "Gibit", "Tibit", "Pibit", "Eibit", "Zibit", "Yibit"],
};

/**
 * Converts a size unit such as "GB", "KiB", "Mbit" or "bytes" into the number
 * of bytes it represents. Returns undefined for anything unknown.
 */
export function bytesPerUnit(unit) {
  const word = unit.toLowerCase();
  if (word === "" || word === "b" || word === "byte" || word === "bytes") return 1;
  if (word === "bit" || word === "bits") return 1 / 8;
  if (!/(b|bytes?|bits?)$/.test(word)) return undefined;

  const isBits = word.endsWith("bit") || word.endsWith("bits");
  const stem = word.replace(/bits?$/, "").replace(/(bytes?|b)$/, "");
  const binary = stem.endsWith("i");
  const prefix = binary ? stem.slice(0, -1) : stem;
  const power = PREFIXES.indexOf(prefix);
  if (prefix === "" || power < 1) return undefined;

  const bytes = (binary ? 1024 : 1000) ** power;
  return isBits ? bytes / 8 : bytes;
}

import test from "node:test";
import assert from "node:assert/strict";

import { formatDuration, formatRate, formatSize, parseDuration, parseRate, parseSize } from "../src/index.mjs";

test("parseSize accepts lower-case and spelled-out units", () => {
  assert.equal(parseSize("3 gb"), 3e9);
  assert.equal(parseSize("12 bytes"), 12);
  assert.equal(parseSize("8 bits"), 1);
});

test("parseSize rejects bare SI prefixes without a byte or bit unit", () => {
  assert.ok(Number.isNaN(parseSize("100 m")));
});

test("parseRate accepts 'per' and periods with their own amount", () => {
  assert.equal(parseRate("60 MB per minute"), 1_000_000);
  assert.equal(parseRate("1 GB / 2s"), 500_000_000);
});

test("parseDuration covers the duration vocabulary", () => {
  assert.equal(parseDuration("1.5h"), 5_400_000);
  assert.equal(parseDuration("2 Weeks"), 1_209_600_000);
  assert.ok(Number.isNaN(parseDuration("soon")));
});

test("formatDuration pluralises from 1.5 units", () => {
  assert.equal(formatDuration(3_600_000 * 1.4, { long: true }), "1 hour");
  assert.equal(formatDuration(3_600_000 * 1.5, { long: true }), "2 hours");
  assert.equal(formatDuration(250, { long: true }), "250 ms");
});

test("formatSize promotes the unit when rounding reaches the next step", () => {
  assert.equal(formatSize(999_999), "1 MB");
  assert.equal(formatSize(-1337), "-1.34 kB");
});

test("formatRate rejects unknown periods", () => {
  assert.throws(() => formatRate(1, { per: "fortnight" }), RangeError);
});
